# Use simple backtracking with MRV heuristic
import sys
sys.setrecursionlimit(10000)

colors = [-1] * n

def is_valid(v, c):
    for nb in adj[v]:
        if colors[nb] == c:
            return False
    return True

def backtrack():
    # Find uncolored vertex with most constraints (MRV)
    uncolored = [i for i in range(n) if colors[i] == -1]
    if not uncolored:
        return True

    # MRV: pick vertex with fewest available colors
    best_v = None
    best_avail = 4
    for v in uncolored:
        used = {colors[nb] for nb in adj[v] if colors[nb] != -1}
        avail = 3 - len(used)
        if avail < best_avail:
            best_avail = avail
            best_v = v
            if avail == 0:
                return False
            if avail == 1:
                break

    v = best_v
    used = {colors[nb] for nb in adj[v] if colors[nb] != -1}
    for c in range(3):
        if c not in used:
            colors[v] = c
            if backtrack():
                return True
            colors[v] = -1
    return False

if backtrack():
    print("SATISFIABLE")
    print(colors)
