def shortest_cycle(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = n + 1
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        q = deque([start])
        dist[start] = 0
        while q:
            v = q.popleft()
            for nb in adj[v]:
                if nb == parent[v]:
                    continue
                if dist[nb] == -1:
                    dist[nb] = dist[v] + 1
                    parent[nb] = v
                    q.append(nb)
                elif nb != parent[v]:
                    cycle_len = dist[v] + dist[nb] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

