import random
from collections import defaultdict, deque

def has_short_cycle(adj, max_len=5):
    """Check if graph has any cycle of length <= max_len"""
    n = len(adj)
    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            v = queue.popleft()
            if dist[v] >= max_len:
                continue
            for u in adj[v]:
                if u not in dist:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    queue.append(u)
                elif u != parent[v] and dist[v] + dist[u] + 1 <= max_len + 1:
                    # Found a cycle
                    return True
    return False

def check_girth(adj):
    """Check the girth of the graph"""
    n = len(adj)
    min_cycle = n + 1
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            v = queue.popleft()
            for u in adj[v]:
                if u not in dist:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    queue.append(u)
                elif u != parent[v]:
                    cycle_len = dist[v] + dist[u] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

