    for combo in itertools.combinations(range(n), 5):
        first_color = coloring[edges.index((combo[0], combo[1]))]
        is_mono = True
        for i in range(5):
            for j in range(i+1, 5):
                if i == 0 and j == 1:
                    continue
                idx = edges.index((combo[i], combo[j]))
                if coloring[idx] != first_color:
                    is_mono = False
                    break
            if not is_mono:
                break
        if is_mono:
            count += 1
    return count

# Try a constructive approach: use a known construction
# For R(5,5), we can try a random coloring and then use local search

best = None
best_count = float('inf')

start = time.time()
for attempt in range(100):
    coloring = [random.randint(0, 1) for _ in range(m)]
    # Simple local search: flip edges that are in monochromatic K5s
    for iteration in range(1000):
        # Find all monochromatic K5s
