def build_adj(colors, n):
    adj = [[0]*n for _ in range(n)]
    idx = 0
    for i in range(n):
        for j in range(i+1, n):
            adj[i][j] = colors[idx]
            adj[j][i] = colors[idx]
            idx += 1
    return adj

